use blr::domain::{
    MeshPrimitive, MeshRecipe, PrimitiveFill, PrimitivePlacement, RecipeError, SceneRecipe,
};

fn add_mesh(
    scene: &mut SceneRecipe,
    name: impl Into<String>,
    primitive: MeshPrimitive,
    location: [f64; 3],
    scale: [f64; 3],
    color: [f64; 4],
) -> Result<(), RecipeError> {
    scene.add(
        MeshRecipe::new(name, primitive)
            .with_placement(PrimitivePlacement {
                location,
                scale,
                ..PrimitivePlacement::default()
            })
            .with_color(color),
    )?;
    Ok(())
}

pub fn scene() -> Result<SceneRecipe, RecipeError> {
    let mut scene = SceneRecipe::new();
    add_mesh(
        &mut scene,
        "foundation",
        MeshPrimitive::Cube {
            size: 3.4,
            calc_uvs: true,
        },
        [0.0, 0.0, 0.35],
        [1.0, 1.0, 0.2],
        [0.22, 0.28, 0.38, 1.0],
    )?;

    for floor in 0..7 {
        let height = 0.8 + floor as f64 * 0.72;
        let width = 2.7 - floor as f64 * 0.24;
        add_mesh(
            &mut scene,
            format!("tower floor {floor}"),
            MeshPrimitive::Cube {
                size: 1.0,
                calc_uvs: true,
            },
            [0.0, 0.0, height],
            [width, width, 0.34],
            [
                0.32 + floor as f64 * 0.045,
                0.48 + floor as f64 * 0.025,
                0.78 - floor as f64 * 0.055,
                1.0,
            ],
        )?;
    }

    add_mesh(
        &mut scene,
        "roof",
        MeshPrimitive::Cone {
            vertices: 8,
            radius1: 1.05,
            radius2: 0.0,
            depth: 1.5,
            end_fill_type: PrimitiveFill::Ngon,
            calc_uvs: true,
        },
        [0.0, 0.0, 6.7],
        [1.0; 3],
        [0.92, 0.37, 0.12, 1.0],
    )?;
    Ok(scene)
}

use std::f64::consts::TAU;

use blr::domain::{
    MeshPrimitive, MeshRecipe, PrimitivePlacement, RecipeError, SceneRecipe, TorusRadii,
};

fn add_mesh(
    scene: &mut SceneRecipe,
    name: impl Into<String>,
    primitive: MeshPrimitive,
    location: [f64; 3],
    rotation: [f64; 3],
    color: [f64; 4],
) -> Result<(), RecipeError> {
    scene.add(
        MeshRecipe::new(name, primitive)
            .with_placement(PrimitivePlacement {
                location,
                rotation,
                ..PrimitivePlacement::default()
            })
            .with_color(color),
    )?;
    Ok(())
}

pub fn scene() -> Result<SceneRecipe, RecipeError> {
    let mut scene = SceneRecipe::new();
    add_mesh(
        &mut scene,
        "central star",
        MeshPrimitive::UvSphere {
            segments: 24,
            ring_count: 12,
            radius: 0.92,
            calc_uvs: true,
        },
        [0.0; 3],
        [0.0; 3],
        [1.0, 0.48, 0.08, 1.0],
    )?;
    add_mesh(
        &mut scene,
        "tilted orbit",
        MeshPrimitive::Torus {
            major_segments: 48,
            minor_segments: 10,
            radii: TorusRadii::MajorMinor {
                major_radius: 2.15,
                minor_radius: 0.07,
            },
            generate_uvs: true,
        },
        [0.0; 3],
        [0.28, 0.16, 0.0],
        [0.16, 0.68, 0.88, 1.0],
    )?;

    for moon in 0..8 {
        let angle = TAU * moon as f64 / 8.0;
        add_mesh(
            &mut scene,
            format!("moon {moon}"),
            MeshPrimitive::UvSphere {
                segments: 12,
                ring_count: 8,
                radius: 0.2 + (moon % 3) as f64 * 0.045,
                calc_uvs: true,
            },
            [2.15 * angle.cos(), 2.15 * angle.sin(), 0.0],
            [0.0; 3],
            [0.38, 0.78 - moon as f64 * 0.035, 0.42, 1.0],
        )?;
    }
    Ok(scene)
}

use blr::domain::{
    MeshPrimitive, MeshRecipe, PrimitiveFill, PrimitivePlacement, RecipeError, SceneRecipe,
    TorusRadii,
};

fn add_mesh(
    scene: &mut SceneRecipe,
    name: &str,
    primitive: MeshPrimitive,
    location: [f64; 3],
    rotation: [f64; 3],
    scale: [f64; 3],
    color: [f64; 4],
) -> Result<(), RecipeError> {
    scene.add(
        MeshRecipe::new(name, primitive)
            .with_placement(PrimitivePlacement {
                location,
                rotation,
                scale,
            })
            .with_color(color),
    )?;
    Ok(())
}

pub fn scene() -> Result<SceneRecipe, RecipeError> {
    let mut scene = SceneRecipe::new();
    add_mesh(
        &mut scene,
        "ground",
        MeshPrimitive::Plane {
            size: 9.0,
            calc_uvs: true,
        },
        [0.0, 0.0, -0.18],
        [0.0; 3],
        [1.0; 3],
        [0.16, 0.22, 0.27, 1.0],
    )?;
    add_mesh(
        &mut scene,
        "beacon base",
        MeshPrimitive::Cube {
            size: 1.1,
            calc_uvs: true,
        },
        [-2.4, 0.0, 0.45],
        [0.0; 3],
        [1.0, 1.0, 0.8],
        [0.8, 0.22, 0.16, 1.0],
    )?;
    add_mesh(
        &mut scene,
        "beacon globe",
        MeshPrimitive::UvSphere {
            segments: 20,
            ring_count: 12,
            radius: 0.72,
            calc_uvs: true,
        },
        [-2.4, 0.0, 1.55],
        [0.0; 3],
        [1.0; 3],
        [0.98, 0.78, 0.18, 1.0],
    )?;
    add_mesh(
        &mut scene,
        "column",
        MeshPrimitive::Cylinder {
            vertices: 20,
            radius: 0.58,
            depth: 2.0,
            end_fill_type: PrimitiveFill::Ngon,
            calc_uvs: true,
        },
        [0.0, 0.0, 0.82],
        [0.0; 3],
        [1.0; 3],
        [0.18, 0.56, 0.78, 1.0],
    )?;
    add_mesh(
        &mut scene,
        "spire",
        MeshPrimitive::Cone {
            vertices: 16,
            radius1: 0.86,
            radius2: 0.0,
            depth: 1.7,
            end_fill_type: PrimitiveFill::Ngon,
            calc_uvs: true,
        },
        [0.0, 0.0, 2.68],
        [0.0; 3],
        [1.0; 3],
        [0.9, 0.36, 0.16, 1.0],
    )?;
    add_mesh(
        &mut scene,
        "frustum",
        MeshPrimitive::Cone {
            vertices: 16,
            radius1: 0.72,
            radius2: 0.3,
            depth: 1.5,
            end_fill_type: PrimitiveFill::Ngon,
            calc_uvs: true,
        },
        [2.35, 0.0, 0.8],
        [0.0; 3],
        [1.0; 3],
        [0.68, 0.32, 0.78, 1.0],
    )?;
    add_mesh(
        &mut scene,
        "ring sculpture",
        MeshPrimitive::Torus {
            major_segments: 32,
            minor_segments: 12,
            radii: TorusRadii::MajorMinor {
                major_radius: 0.82,
                minor_radius: 0.14,
            },
            generate_uvs: true,
        },
        [2.35, 0.0, 1.95],
        [0.65, 0.2, 0.0],
        [1.0; 3],
        [0.16, 0.82, 0.58, 1.0],
    )?;
    Ok(scene)
}

use blr::domain::{MeshPrimitive, MeshRecipe, PrimitivePlacement, RecipeError, SceneRecipe};

fn add_tile(
    scene: &mut SceneRecipe,
    name: String,
    location: [f64; 3],
    scale: [f64; 3],
    color: [f64; 4],
) -> Result<(), RecipeError> {
    scene.add(
        MeshRecipe::new(
            name,
            MeshPrimitive::Cube {
                size: 1.0,
                calc_uvs: true,
            },
        )
        .with_placement(PrimitivePlacement {
            location,
            scale,
            ..PrimitivePlacement::default()
        })
        .with_color(color),
    )?;
    Ok(())
}

pub fn scene() -> Result<SceneRecipe, RecipeError> {
    let mut scene = SceneRecipe::new();
    let cells = 8;
    for x in 0..cells {
        for y in 0..cells {
            let fx = x as f64 / (cells - 1) as f64;
            let fy = y as f64 / (cells - 1) as f64;
            let wave = (fx * 9.0).sin() * (fy * 8.0).cos();
            let height = 0.34 + (wave + 1.0) * 0.44;
            let color = [
                0.13 + fx * 0.18,
                0.3 + fy * 0.42,
                0.19 + (wave + 1.0) * 0.12,
                1.0,
            ];
            add_tile(
                &mut scene,
                format!("tile {x}-{y}"),
                [x as f64 - 3.5, y as f64 - 3.5, height * 0.5],
                [0.47, 0.47, height * 0.5],
                color,
            )?;
        }
    }
    Ok(scene)
}
